import React from "react";

type TiledBackgroundPuzzleWrapperProps =
  React.HTMLAttributes<HTMLDivElement> & {
    children: React.ReactNode;
    className?: string;
    backgroundImage: string;
    darkModeBackgroundImage?: string;
    isPixelImage?: boolean;
    backgroundOffsetY?: number | string;
  };

export function TiledBackgroundPuzzleWrapper({
  children,
  className = "",
  backgroundImage,
  darkModeBackgroundImage,
  isPixelImage = false,
  backgroundOffsetY = -48,
  ...props
}: TiledBackgroundPuzzleWrapperProps) {
  const resolvedOffsetY =
    typeof backgroundOffsetY === "number"
      ? `${backgroundOffsetY}px`
      : backgroundOffsetY;
  const style = {
    ...(props.style || {}),
    ["--bg-url"]: `url(${backgroundImage})`,
    ...(darkModeBackgroundImage
      ? { ["--bg-url-dark"]: `url(${darkModeBackgroundImage})` }
      : {}),
    ...(isPixelImage ? { imageRendering: "pixelated" } : {}),
    ...(resolvedOffsetY !== undefined
      ? { backgroundPosition: `left ${resolvedOffsetY}` }
      : {}),
  } as React.CSSProperties & Record<`--${string}`, string>;

  return (
    <div
      {...props}
      style={style}
      className={[
        // choose which var via classes (dark wins)
        "[background-image:var(--bg-url)]",
        ...(darkModeBackgroundImage
          ? ["dark:[background-image:var(--bg-url-dark)]"]
          : []),

        // tiling settings
        "bg-repeat bg-auto bg-left-top",

        // layout/text (adjust as needed)
        "aspect-16/9 text-black min-h-screen pb-0 lg:pb-8",
        className,
      ].join(" ")}
    >
      <div className="[image-rendering:auto] w-full h-full">{children}</div>
    </div>
  );
}
