import { cn } from "@hunt/styled-ui";
import React from "react";
import { type PuzzleTitleProps } from "../PuzzleLayout";
import { TiledBackgroundPuzzleWrapper } from "../TiledBackgroundPuzzleWrapper";
import blueBackground from "./assets/background/blue.png";
import purpleBackground from "./assets/background/purple.png";
import redBackground from "./assets/background/red.png";

/** ---------------- Shared Types ---------------- */
type DivProps = React.HTMLAttributes<HTMLDivElement> & {
  className?: string;
  children: React.ReactNode;
};

type HeaderProps = React.HTMLAttributes<HTMLElement> & {
  className?: string;
  children: React.ReactNode;
  /** Make the header itself glassy instead of just the inner container */
  glassOnHeader?: boolean;
};

/** ---------------- Reusable class bundles ---------------- */

export const hbSection =
  "bg-black/75 border border-white/10 rounded-xl shadow-xl";

/** Base wrapper factory; each theme provides stronger color overrides via CSS vars */
function Wrapper({
  children,
  className = "",
  backgroundImage,
  ...props
}: DivProps & { backgroundImage?: string }) {
  return backgroundImage ? (
    <TiledBackgroundPuzzleWrapper
      {...props}
      backgroundImage={backgroundImage}
      isPixelImage={true}
      className={className}
    >
      {children}
    </TiledBackgroundPuzzleWrapper>
  ) : (
    <div
      {...props}
      className={cn(
        "relative isolate min-h-dvh text-gray-800 p-0 lg:pb-8",
        "hb-space",
        className,
      )}
    >
      {children}
    </div>
  );
}

/** ---------------- Public Wrappers ----------------
 * Vivid color overrides per theme using Tailwind arbitrary properties.
 * These override the defaults defined in the hb-space utility.
 */

export function BluePuzzleWrapper(props: DivProps) {
  return (
    <Wrapper {...props} backgroundImage={blueBackground} className="hb-blue" />
  );
}

export function RedPuzzleWrapper(props: DivProps) {
  return (
    <Wrapper {...props} backgroundImage={redBackground} className="hb-red" />
  );
}

export function PurplePuzzleWrapper(props: DivProps) {
  return (
    <Wrapper
      {...props}
      backgroundImage={purpleBackground}
      className="hb-purple"
    />
  );
}

function BaseHeader({ children, className = "", ...props }: HeaderProps) {
  return (
    <header
      {...props}
      className={cn(
        "relative p-2 sm:p-4 md:p-8 pt-24 sm:pt-24 md:pt-24",
        className,
      )}
    >
      <div id="puzzle-guess-section">{children}</div>
    </header>
  );
}

export function BluePuzzleHeader(props: HeaderProps) {
  return <BaseHeader {...props} />;
}
export function RedPuzzleHeader(props: HeaderProps) {
  return <BaseHeader {...props} />;
}
export function PurplePuzzleHeader(props: HeaderProps) {
  return <BaseHeader {...props} />;
}

export function HSpacePuzzleTitle({
  children,
  className = "",
  ...props
}: PuzzleTitleProps) {
  return (
    <h1
      {...props}
      className={cn(
        "pt-2 text-center font-bold text-white transform-gpu drop-shadow-[0_2px_2px_rgba(0,0,0,0.75)]",
        className,
      )}
    >
      {children}
    </h1>
  );
}

// PuzzleBacklink
type PuzzleBacklinkProps = React.AnchorHTMLAttributes<HTMLAnchorElement> & {
  children: React.ReactNode;
  className?: string;
};

export function HSpacePuzzleBacklink({
  children,
  className = "",
  ...props
}: PuzzleBacklinkProps) {
  return (
    <a
      {...props}
      className={cn(
        "flex items-center ml-1 gap-1 w-fit no-underline rounded-xl pr-4 pl-3.5 py-2 bg-white/[0.7] backdrop-blur-md text-secondary hover:text-primary focus-visible:text-primary transition-colors duration-150 hover:bg-white/[0.8] focus-visible:bg-white/[0.8] shadow-lg focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent",
        className,
      )}
    >
      {children}
    </a>
  );
}
