import {
  autoUpdate,
  flip,
  offset,
  safePolygon,
  shift,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useRole,
} from "@floating-ui/react";
import type { TeamHuntState } from "@hunt/public-client";
import {
  type ResolvedCutsceneContent,
  CutsceneDisplay,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { CheckCircle } from "lucide-react";
import React, { useMemo, useState } from "react";
import {
  PuzzleIcon,
  usePuzzleState,
} from "../../../components/PuzzleAndTaskDisplay/PuzzleCard";
import {
  TeamStateProvider,
  useTeamState,
} from "../../../components/TeamStateProvider";
import { TiledBackgroundPuzzleWrapper } from "../../../components/TiledBackgroundPuzzleWrapper";
import { PuzzleTooltipComponent } from "../../../components/Tooltip";
import { hbSection } from "../../../components/hyperbolic_space/HyperbolicSpacePuzzleLayout";
import background from "./assets/HS_background_color.png";
import purpleBackground from "./assets/purple_background.png";
import type {
  HyperbolicSpaceState,
  HyperbolicSpacePuzzleDisplay,
} from "./types";

const MAP_NATIVE_WIDTH = 1920;
const MAP_NATIVE_HEIGHT = 1080;

// Tooltip wrapper for puzzle links and map entities
const PuzzleTooltipWrapper = ({
  puzzleDisplay,
  children,
  placement = "right",
  as = "a",
  href,
  className,
  style,
  ...rest
}: {
  puzzleDisplay: HyperbolicSpacePuzzleDisplay;
  children: React.ReactNode;
  placement?: "right" | "top" | "bottom" | "left";
  as?: "a" | "button";
  href?: string;
  className?: string;
  style?: React.CSSProperties;
}) => {
  const { epoch } = useTeamState();
  const [showTooltip, setShowTooltip] = useState(false);

  const { refs, floatingStyles, context } = useFloating({
    placement,
    open: showTooltip,
    onOpenChange: setShowTooltip,
    middleware: [offset(5), flip(), shift()],
    whileElementsMounted: autoUpdate,
  });

  const hover = useHover(context, { move: false, handleClose: safePolygon() });
  const focus = useFocus(context);
  const role = useRole(context, { role: "label" });
  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    role,
  ]);

  // Get up-to-date puzzle state for tooltip
  const puzzleStateHandle = usePuzzleState(epoch, puzzleDisplay.puzzle);
  const puzzleState = puzzleStateHandle[0];

  const tooltip = showTooltip && (
    <PuzzleTooltipComponent
      innerRef={refs.setFloating}
      style={{
        ...floatingStyles,
        visibility: "visible",
        zIndex: 100,
      }}
      title={puzzleState.title}
      answer={puzzleState.answer}
      desc={puzzleState.desc}
      lockState={puzzleState.state}
      nsfw={puzzleDisplay.puzzle.nsfw}
      {...getFloatingProps()}
    />
  );

  // Render as <a> or <button> as needed
  const Tag = as;
  return (
    <>
      <Tag
        ref={refs.setReference}
        {...getReferenceProps()}
        href={href}
        className={className}
        style={style}
        {...rest}
      >
        {children}
      </Tag>
      {tooltip}
    </>
  );
};

const HyperbolicSpaceBody = ({
  state,
  teamState,
  cutsceneContent,
}: {
  state: HyperbolicSpaceState;
  teamState: TeamHuntState;
  cutsceneContent?: ResolvedCutsceneContent[];
}) => {
  const [hoveredPuzzle, setHoveredPuzzle] = useState<string | null>(null);
  const solvedPuzzleSet = useMemo(
    () =>
      new Set(
        state.puzzles
          .filter((puzzle) => puzzle.puzzle.answer)
          .map((puzzle) => puzzle.puzzle.slug),
      ),
    [state.puzzles],
  );

  return (
    <TeamStateProvider teamState={teamState}>
      <TiledBackgroundPuzzleWrapper
        backgroundImage={purpleBackground}
        isPixelImage={true}
      >
        <div className="flex flex-col min-h-screen gap-8">
          <HyperbolicSpaceMapSection
            state={state}
            hoveredPuzzle={hoveredPuzzle}
            setHoveredPuzzle={setHoveredPuzzle}
            solvedPuzzleSet={solvedPuzzleSet}
          />
          <div className="w-full flex justify-center pb-8">
            <div className={cn("w-full max-w-screen-lg px-4 py-8", hbSection)}>
              <HyperbolicSpaceMetaPuzzleSection state={state} />
              <HyperbolicSpacePuzzleListSection state={state} />
            </div>
          </div>
        </div>
      </TiledBackgroundPuzzleWrapper>
      <CutsceneDisplay content={cutsceneContent} />
    </TeamStateProvider>
  );
};

function HyperbolicSpaceMapSection({
  state,
  hoveredPuzzle,
  setHoveredPuzzle,
  solvedPuzzleSet,
}: {
  state: HyperbolicSpaceState;
  hoveredPuzzle: string | null;
  setHoveredPuzzle: React.Dispatch<React.SetStateAction<string | null>>;
  solvedPuzzleSet: Set<string>;
}) {
  const hoveredSolved = Boolean(
    hoveredPuzzle && solvedPuzzleSet.has(hoveredPuzzle),
  );
  return (
    <div className="w-full flex justify-center items-start">
      <div
        className="relative w-full max-w-screen-2xl"
        style={{
          aspectRatio: `${MAP_NATIVE_WIDTH} / ${MAP_NATIVE_HEIGHT}`,
        }}
      >
        {/* Background */}
        <img
          src={background}
          alt="Hyperbolic Space Page Background"
          className="w-full h-auto select-none pointer-events-none absolute inset-0 z-0"
        />

        <div id="main-content">
          {/* Title: Hyperbolic Space */}
          <div
            className="absolute text-white font-bold z-10"
            style={{
              top: `calc(150 / ${MAP_NATIVE_HEIGHT} * 100%)`,
              left: `calc(800 / ${MAP_NATIVE_WIDTH} * 100%)`,
              fontSize: `calc(48 / ${MAP_NATIVE_WIDTH} * 100vw)`,
              lineHeight: 1.1,
            }}
          >
            Hyperbolic Space
          </div>

          {/* Puzzle overlays */}
          <div className="absolute inset-0 w-full h-full z-0">
            {state.puzzles.map((puzzle) => (
              <HyperbolicSpaceMapEntity
                key={puzzle.puzzle.title}
                puzzleDisplay={puzzle}
                onHover={() => {
                  setHoveredPuzzle(puzzle.puzzle.slug);
                }}
                onMouseLeave={() => {
                  setHoveredPuzzle(null);
                }}
                shouldGlow={Boolean(
                  hoveredPuzzle &&
                    hoveredSolved &&
                    state.hover_list[hoveredPuzzle]?.includes(
                      puzzle.puzzle.slug,
                    ),
                )}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function HyperbolicSpaceMetaPuzzleSection({
  state,
}: {
  state: HyperbolicSpaceState;
}) {
  return (
    <>
      {state.puzzles
        .filter(
          (p) =>
            p.puzzle.slug === "hyperbolic_space" &&
            p.puzzle.state === "unlocked",
        )
        .map((puzzle) => (
          <div
            className="flex flex-row w-full items-center justify-center mb-8 gap-4"
            key={puzzle.puzzle.slug}
          >
            <a
              href={`/puzzles/${puzzle.puzzle.slug}`}
              className="text-3xl font-extrabold text-purple-600 hover:text-purple-700 active:text-purple-800 dark:text-purple-300 dark:hover:text-purple-200 dark:active:text-purple-100 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-purple-500 dark:focus:ring-purple-400 dark:focus:ring-offset-gray-900 flex items-center gap-2"
            >
              <PuzzleIcon
                lockState={puzzle.puzzle.state}
                solved={!!puzzle.puzzle.answer}
                className={
                  !puzzle.puzzle.answer
                    ? "text-purple-600 dark:text-purple-400"
                    : undefined
                }
              />
              Hyperbolic Space
            </a>
            <span className="text-3xl text-green-500">
              {puzzle.puzzle.answer}
            </span>
          </div>
        ))}
    </>
  );
}

function HyperbolicSpacePuzzleListSection({
  state,
}: {
  state: HyperbolicSpaceState;
}) {
  return (
    <div className="grid grid-cols-2 gap-20">
      {/* Left column (red) */}
      <HyperbolicSpacePuzzleColumn
        puzzles={state.puzzles.filter((puzzle) => puzzle.color === "red")}
        color="red"
      />
      {/* Right column (blue) */}
      <HyperbolicSpacePuzzleColumn
        puzzles={state.puzzles.filter((puzzle) => puzzle.color === "blue")}
        color="blue"
      />
    </div>
  );
}

function HyperbolicSpacePuzzleColumn({
  puzzles,
  color,
}: {
  puzzles: HyperbolicSpacePuzzleDisplay[];
  color: "red" | "blue";
}) {
  const colorClass =
    color === "red"
      ? {
          text: "text-red-600",
          hover: "hover:text-red-700",
          active: "active:text-red-800",
          dark: "dark:text-red-300 dark:hover:text-red-200 dark:active:text-red-100",
          ring: "focus:ring-red-500 dark:focus:ring-red-400 dark:focus:ring-offset-gray-900",
          icon: "text-red-600 dark:text-red-400",
        }
      : {
          text: "text-blue-600",
          hover: "hover:text-blue-700",
          active: "active:text-blue-800",
          dark: "dark:text-blue-300 dark:hover:text-blue-200 dark:active:text-blue-100",
          ring: "focus:ring-blue-500 dark:focus:ring-blue-400 dark:focus:ring-offset-gray-900",
          icon: "text-blue-600 dark:text-blue-400",
        };

  return (
    <div className="flex flex-col items-start justify-center gap-2">
      {puzzles.map((puzzle) => (
        <div
          key={puzzle.puzzle.slug}
          className="flex flex-row w-full items-center"
        >
          <a
            href={`/puzzles/${puzzle.puzzle.slug}`}
            className={cn(
              "w-80 text-lg font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 flex items-center gap-2",
              colorClass.text,
              colorClass.hover,
              colorClass.active,
              colorClass.dark,
              colorClass.ring,
            )}
          >
            <PuzzleIcon
              lockState={puzzle.puzzle.state}
              solved={!!puzzle.puzzle.answer}
              className={!puzzle.puzzle.answer ? colorClass.icon : undefined}
            />
            {puzzle.puzzle.title}
          </a>
          <span className="text-lg text-green-500">{puzzle.puzzle.answer}</span>
        </div>
      ))}
    </div>
  );
}

const HyperbolicSpaceMapEntity = ({
  puzzleDisplay,
  onHover,
  onMouseLeave,
  shouldGlow,
}: {
  puzzleDisplay: HyperbolicSpacePuzzleDisplay;
  onHover?: () => void;
  onMouseLeave?: () => void;
  shouldGlow?: boolean;
}) => {
  const { epoch } = useTeamState();
  const [showTooltip, setShowTooltip] = useState(false);

  const { refs, context } = useFloating({
    placement: "right",
    open: showTooltip,
    onOpenChange: setShowTooltip,
    middleware: [offset(5), flip(), shift()],
    whileElementsMounted: autoUpdate,
  });

  const hover = useHover(context, { move: false, handleClose: safePolygon() });
  const focus = useFocus(context);
  const role = useRole(context, { role: "label" });
  const { getReferenceProps } = useInteractions([hover, focus, role]);

  // Dynamic computed styles for positioning remain inline
  const dynamicContainerStyle = {
    top: `${(puzzleDisplay.pos.top / MAP_NATIVE_HEIGHT) * 100}%`,
    left: `${(puzzleDisplay.pos.left / MAP_NATIVE_WIDTH) * 100}%`,
    width: `${(puzzleDisplay.pos.width / MAP_NATIVE_WIDTH) * 100}%`,
  };

  const puzzleStateHandle = usePuzzleState(epoch, puzzleDisplay.puzzle);
  const puzzleState = puzzleStateHandle[0];

  return (
    <>
      <PuzzleTooltipWrapper
        puzzleDisplay={puzzleDisplay}
        as="a"
        href={`/puzzles/${puzzleState.slug}`}
        className="block absolute"
        style={{
          ...dynamicContainerStyle,
          height: "auto",
        }}
      >
        <span className="relative block w-full h-full">
          <span className="block w-full h-full">
            {/* The image should fill the container */}
            <img
              ref={refs.setReference}
              {...getReferenceProps()}
              src={puzzleDisplay.asset}
              alt={puzzleDisplay.puzzle.title}
              onMouseEnter={onHover}
              onMouseLeave={onMouseLeave}
              draggable={false}
              className={cn(
                "block w-full h-full object-contain select-none pointer-events-auto cursor-pointer transition duration-300 ease-in-out hover:brightness-200 transform-gpu hover:drop-shadow-[0_0_18px_rgba(255,255,255,0.8)]",
                shouldGlow &&
                  "brightness-200 transform-gpu drop-shadow-[0_0_18px_rgba(255,255,255,0.8)]",
              )}
            />
          </span>
          {puzzleState.answer && (
            <span className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <CheckCircle className="w-5 h-5 text-white-600 drop-shadow" />
            </span>
          )}
        </span>
      </PuzzleTooltipWrapper>
    </>
  );
};

export default HyperbolicSpaceBody;
