import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";
import React, { useMemo } from "react";
import { hydrateRoot } from "react-dom/client";
import useDataset from "../../../client/useDataset";
import {
  applySolvedMapToPuzzleDisplays,
  useSolvedPuzzlesState,
} from "../../../components/puzzleSolveLocalState";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import HyperbolicSpaceBody from "./HyperbolicSpaceBody";
import { buildHyperbolicSpaceHoverList } from "./hoverList";
import { type HyperbolicSpaceState } from "./types";

const HyperbolicSpaceManager = ({
  initialState,
  initialTeamState,
  cutsceneContent,
}: {
  initialState: HyperbolicSpaceState;
  initialTeamState: TeamHuntState;
  cutsceneContent: ResolvedCutsceneContent[];
}) => {
  const state = useDataset("hyperbolic_space", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const { solvedMap } = useSolvedPuzzlesState();
  const mergedPuzzles = useMemo(() => {
    if (!IS_STATIC_SITE) return state.puzzles;
    return applySolvedMapToPuzzleDisplays(state.puzzles, solvedMap);
  }, [state.puzzles, solvedMap]);
  const mergedHoverList = useMemo(() => {
    if (!IS_STATIC_SITE) return state.hover_list;
    return buildHyperbolicSpaceHoverList(mergedPuzzles);
  }, [mergedPuzzles, state.hover_list]);
  const mergedState = useMemo(() => {
    if (
      mergedPuzzles === state.puzzles &&
      mergedHoverList === state.hover_list
    ) {
      return state;
    }
    return { ...state, puzzles: mergedPuzzles, hover_list: mergedHoverList };
  }, [mergedHoverList, mergedPuzzles, state]);
  return (
    <HyperbolicSpaceBody
      state={mergedState}
      teamState={teamState}
      cutsceneContent={cutsceneContent}
    />
  );
};

const elem = document.getElementById("hyperbolic-space-root");
if (elem) {
  const state = (
    window as unknown as { initialHyperbolicSpaceState: HyperbolicSpaceState }
  ).initialHyperbolicSpaceState;
  const teamState = (window as unknown as { initialTeamState: TeamHuntState })
    .initialTeamState;
  const cutsceneContent = (
    window as unknown as { initialCutsceneContent: ResolvedCutsceneContent[] }
  ).initialCutsceneContent;
  hydrateRoot(
    elem,
    <HyperbolicSpaceManager
      initialState={state}
      initialTeamState={teamState}
      cutsceneContent={cutsceneContent}
    />,
  );
} else {
  console.error(
    "Could not mount HyperbolicSpaceManager because #hyperbolic-space-root was nowhere to be found",
  );
}
