export const buildHyperbolicSpaceHoverList = (
  puzzles: HyperbolicSpacePuzzleDisplay[],
): Record<string, string[]> => {
  if (!puzzles.length) return {};
  const puzzleBySlug = new Map(
    puzzles.map((puzzle) => [puzzle.puzzle.slug, puzzle]),
  );
  return Object.fromEntries(
    Object.entries(HYPERBOLIC_SPACE_ADJACENT_PUZZLES)
      .filter(([slug]) => puzzleBySlug.get(slug)?.puzzle.answer)
      .map(([slug, neighbors]) => [
        slug,
        neighbors.filter(
          (neighbor) => puzzleBySlug.get(neighbor)?.puzzle.state === "unlocked",
        ),
      ]),
  );
};
